use std::{fs,path::Path,process::Command};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/paired-callers");let s=r.join("source");let p=s.join("crates/zopro-bn254/src/ifma.rs");let source=fs::read_to_string(&p).unwrap();assert_eq!(source.matches("_mm256_and_si512").count(),8);fs::write(r.join("ifma-first-build.rs"),&source).unwrap();let setup=fs::read_to_string(r.join("setup.rs")).unwrap();fs::write(r.join("setup-first-build.rs"),&setup).unwrap();fs::write(r.join("setup.rs"),setup.replace(".replace(\"_mm512_\",\"_mm256_\")",".replace(\"_mm512_\",\"_mm256_\").replace(\"_si512\",\"_si256\")")).unwrap();fs::copy(r.join("integration-audit.json"),r.join("integration-audit-first-build.json")).unwrap();let old_eight=hash(s.join("crates/zopro-bn254/src/ifma8.rs"));fs::write(&p,source.replace("_si512","_si256")).unwrap();let status=Command::new("python3").arg(s.join("scripts/ifma8.py")).status().unwrap();assert!(status.success());let status=Command::new("python3").args([s.join("scripts/ifma8.py").to_str().unwrap(),"--check"]).status().unwrap();assert!(status.success());assert_eq!(hash(s.join("crates/zopro-bn254/src/ifma8.rs")),old_eight);let mut a:Value=serde_json::from_slice(&fs::read(r.join("integration-audit.json")).unwrap()).unwrap();a["new_ifma_sha256"]=json!(hash(&p));a["translation"]=json!("Test-free prior method body only; Ifma8->Ifma, _mm512_-> _mm256_ and _si512-> _si256; official generator reconstructs the exact same eight-lane source as before the four-lane naming repair");a["repair"]=json!({"failed_build":"fresh-build.log","failed_source":"ifma-first-build.rs","eight_lane_source_changed":false,"timings_started":false});fs::write(r.join("integration-audit.json"),serde_json::to_vec_pretty(&a).unwrap()).unwrap();}
